"url": "../amc-bank/official-solutions/AMC10A_2021_Fall_Solutions.pdf",
"sourceURL": "https://www.isinj.com/mt-amc10/2021-AMC-10A-Solutions%28fall%29.pdf",
"label": "Fall 2021 AMC 10 A Official Solutions",
"attribution": "Mathematical Association of America (MAA)",
"license": "CC-BY-NC-SA-4.0",
